select case when sqft >= 17237 then 'HIGH' else 'LOW' end as sqft_tier, count(*) filter (where city = 'Berlin') as berlin_rows, sum(case when region = 'Central' then sqft else 0 end) as central_sqft, sort_array(collect_set(region)) as region_list, round(sum(sqft) / nullif(count(case when city = 'London' then 1 end), 0), 2) as sqft_per_london from stores group by case when sqft >= 17237 then 'HIGH' else 'LOW' end;
